// Logic Gate: Filter leads that need outreach today
const leads = $input.all().map(i => i.json);
const today = new Date();
const readyLeads = [];

for (const lead of leads) {
  const status = (lead['Status'] || '').toUpperCase();
  if (['WON', 'LOST', 'IDLE', 'QUALIFIED', 'PROPOSAL', 'AUDIT_SENT', 'CALL_SCHEDULED'].includes(status)) continue;
  if (!lead['Email']) continue;

  // Parse attempt from Notes (stores tags like 'Outreach: C_MED_01')
  const notes = lead['Notes'] || '';
  let attemptNumber = 0;
  const tagMatch = notes.match(/Outreach:\s*[A-Z]_[A-Z]+_(\d+|EXIT)/i);
  if (tagMatch) {
    const suffix = tagMatch[1].toUpperCase();
    if (suffix === 'EXIT') attemptNumber = 4;
    else attemptNumber = parseInt(suffix) || 0;
  }
  if (attemptNumber >= 4) continue;

  // Parse last contact date - handle ########, empty, and invalid dates
  let lastTouch = null;
  const rawDate = lead['Last Contact Date'];
  if (rawDate && !String(rawDate).includes('#')) {
    const parsed = new Date(rawDate);
    if (!isNaN(parsed.getTime())) {
      lastTouch = parsed;
    }
  }

  const daysSinceLastTouch = lastTouch ? Math.floor((today - lastTouch) / (1000 * 60 * 60 * 24)) : 999;

  let shouldSend = false;
  let nextAttempt = attemptNumber;

  if (!lastTouch && attemptNumber <= 0) { shouldSend = true; nextAttempt = 1; }
  else if (attemptNumber <= 1 && daysSinceLastTouch >= 3) { shouldSend = true; nextAttempt = 2; }
  else if (attemptNumber === 2 && daysSinceLastTouch >= 4) { shouldSend = true; nextAttempt = 3; }
  else if (attemptNumber === 3 && daysSinceLastTouch >= 6) { shouldSend = true; nextAttempt = 4; }

  if (shouldSend) {
    readyLeads.push({ ...lead, attemptNumber: nextAttempt, daysSinceLastTouch });
  }
}

return readyLeads.map(lead => ({ json: lead }));

const items = $input.all();
return items.map(item => {
