  const routes = { 'med_spa': 'med_spa', 'realtor': 'realtor', 'law_firm': 'law_firm', 'hvac_home_services': 'hvac' };
  return { json: { ...item.json, _route: industry, _routeKey: routes[industry] || 'other' } };
});

